using UnityEngine;

/// <summary>
/// 道具数据资产（ScriptableObject）— 定义一种道具的所有静态属性。
/// 右键 -> Create -> Game -> Item Data 创建。
/// 参考: 以撒的结合道具 / 崩坏星穹铁道奇物 / 明日方舟藏品。
/// </summary>
[CreateAssetMenu(fileName = "NewItem", menuName = "Game/Item Data")]
public class ItemData : ScriptableObject
{
    [Header("基本信息")]
    [Tooltip("唯一标识，如 'blood_of_martyr'")]
    public string itemId;              // 唯一标识
    public string itemName;            // 显示名称
    [TextArea] public string description;
    public Sprite icon;
    [Tooltip("品质: Common/Uncommon/Rare/Legendary")]
    public ItemQuality quality;        // 品质

    [Header("效果（策略模式）")]
    [Tooltip("拖入具体效果资产: ItemEffectBase 子类")]
    public ItemEffectBase effect;      // 道具效果策略
}

using UnityEngine;

/// <summary>
/// 道具效果抽象基类 — 策略模式，定义道具被获得/移除时的行为。
/// 与 SkillEffectBase 类似，每个具体效果是独立的 ScriptableObject 资产。
///
/// 子类:
///   StatModifierEffect — 直接修改属性
///   ApplyBuffEffect    — 挂载 Buff（道具系统与 Buff 系统的主要桥接）
///   ConditionalEffect  — 条件触发效果
/// </summary>
public abstract class ItemEffectBase : ScriptableObject
{
    /// <summary>道具被获得时调用</summary>
    public abstract void OnAcquire(GameObject owner);

    /// <summary>道具被移除时调用（清理副作用）</summary>
    public abstract void OnRemove(GameObject owner);
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具管理器 — 管理玩家当前持有的所有道具。
/// 挂载在 Player GameObject 上，通过 PlayerManager 的持久化机制自动跟随跨场景。
///
/// 核心职责:
///   1. 管理道具集合（添加/移除/查询）
///   2. 执行道具效果（OnAcquire / OnRemove）
///   3. 通知事件（供 UI Controller 监听）
/// </summary>
public class ItemManager : MonoBehaviour
{
    [Header("调试")]
    [SerializeField] private List<ItemData> _initialItems; // Inspector 调试用

    private readonly List<ItemData> _items = new List<ItemData>();
    private readonly Dictionary<string, ItemData> _itemDict = new Dictionary<string, ItemData>();

    /// <summary>当前道具列表（只读）</summary>
    public IReadOnlyList<ItemData> Items => _items;

    /// <summary>道具数量</summary>
    public int Count => _items.Count;

    // ========== 事件 ==========

    /// <summary>道具获得: (itemData)</summary>
    public event Action<ItemData> OnItemAcquired;

    /// <summary>道具移除: (itemData)</summary>
    public event Action<ItemData> OnItemRemoved;

    // ========== Unity 生命周期 ==========

    private void Start()
    {
        // Inspector 调试：自动获得初始道具
        foreach (var item in _initialItems)
        {
            if (item != null)
                AcquireItem(item);
        }
    }

    // ========== 核心方法 ==========

    /// <summary>
    /// 获得道具 — 执行效果 + 加入集合 + 事件通知。
    /// 如果已有相同 itemId 的道具，返回 false（不重复添加）。
    /// </summary>
    public bool AcquireItem(ItemData item)
    {
        if (item == null || _itemDict.ContainsKey(item.itemId))
            return false;

        // 执行道具效果
        item.effect?.OnAcquire(gameObject);

        _items.Add(item);
        _itemDict[item.itemId] = item;

        OnItemAcquired?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 移除道具 — 执行清理 + 从集合移除 + 事件通知。
    /// </summary>
    public bool RemoveItem(string itemId)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        item.effect?.OnRemove(gameObject);
        _items.Remove(item);
        _itemDict.Remove(itemId);

        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>是否有指定道具</summary>
    public bool HasItem(string itemId) => _itemDict.ContainsKey(itemId);

    /// <summary>获取道具</summary>
    public ItemData GetItem(string itemId)
        => _itemDict.TryGetValue(itemId, out var item) ? item : null;
}

using UnityEngine;

/// <summary>
/// 属性修改道具效果 — 直接修改 PlayerStats 中某个字段的值。
/// 适用于简单的一次性属性加成道具。
///
/// 示例: "力量腰带" → statName="MaxHealth", percentBonus=1.3f, isMultiplicative=true
///        "疾风之靴" → statName="MoveSpeed", flatBonus=2f
/// </summary>
[CreateAssetMenu(fileName = "StatModifierEffect", menuName = "Game/Item Effect/Stat Modifier")]
public class StatModifierEffect : ItemEffectBase
{
    [Header("属性修改")]
    [Tooltip("属性名: MaxHealth / MoveSpeed / AttackStrength / BulletSpeed / ShootCooldown / ColliderRadius")]
    public string statName;

    [Tooltip("固定加成值")]
    public float flatBonus;

    [Tooltip("百分比加成: 1.3 = +30%, 0.7 = -30%")]
    public float percentBonus = 1f;

    [Tooltip("true = 乘算, false = 加算（先乘再加）")]
    public bool isMultiplicative = true;

    private float _originalValue;
    private bool _applied;

    public override void OnAcquire(GameObject owner)
    {
        var stats = owner.GetComponent<PlayerStats>();
        if (stats == null)
        {
            Debug.LogWarning($"StatModifierEffect: owner '{owner.name}' 没有 PlayerStats 组件");
            return;
        }

        float current = stats.GetStatValue(statName);
        _originalValue = current;

        float newValue = isMultiplicative
            ? current * percentBonus + flatBonus
            : current + flatBonus + current * (percentBonus - 1f);

        stats.SetStatValue(statName, newValue);
        _applied = true;
    }

    public override void OnRemove(GameObject owner)
    {
        if (!_applied) return;

        var stats = owner.GetComponent<PlayerStats>();
        if (stats != null)
            stats.SetStatValue(statName, _originalValue);

        _applied = false;
    }
}

using UnityEngine;

/// <summary>
/// 挂载 Buff 道具效果 — 获得道具时给持有者永久挂载一个 Buff。
/// 这是道具系统与 Buff 系统的主要桥接方式。
///
/// 示例: "毒蛇之牙" → 挂载 OnHitBuff，攻击时给敌人上毒
///        "吸血鬼之触" → 挂载 HOBuff，攻击命中时回血
/// </summary>
[CreateAssetMenu(fileName = "ApplyBuffEffect", menuName = "Game/Item Effect/Apply Buff")]
public class ApplyBuffEffect : ItemEffectBase
{
    [Header("Buff 配置")]
    [Tooltip("要挂载的 Buff 数据资产")]
    public BuffData buffData;

    /// <summary>挂载的 Buff 实例（用于 OnRemove 时移除）</summary>
    private BuffInstance _appliedBuff;

    public override void OnAcquire(GameObject owner)
    {
        if (buffData == null)
        {
            Debug.LogWarning("ApplyBuffEffect: buffData 为空！");
            return;
        }

        var buffManager = owner.GetComponent<BuffManager>();
        if (buffManager == null)
        {
            Debug.LogWarning($"ApplyBuffEffect: owner '{owner.name}' 没有 BuffManager 组件");
            return;
        }

        _appliedBuff = buffManager.ApplyBuff(buffData, owner);
    }

    public override void OnRemove(GameObject owner)
    {
        if (_appliedBuff == null) return;

        var buffManager = owner.GetComponent<BuffManager>();
        buffManager?.RemoveBuff(_appliedBuff);
        _appliedBuff = null;
    }
}

using System;
using UnityEngine;

/// <summary>
/// 条件触发道具效果 — 监听指定事件，条件满足时执行子效果。
/// 适用于 "当 X 发生时做 Y" 类型的道具。
///
/// 示例:
///   "复仇之盾" — triggerEvent=OnDamaged, executeEffect=AoE伤害效果
///   "不死鸟之羽" — triggerEvent=OnHealthBelow(20%), executeEffect=回满血效果
/// </summary>
[CreateAssetMenu(fileName = "ConditionalEffect", menuName = "Game/Item Effect/Conditional")]
public class ConditionalEffect : ItemEffectBase
{
    [Header("触发条件")]
    [Tooltip("触发事件类型")]
    public ItemTriggerEvent triggerEvent;

    [Header("条件参数")]
    [Tooltip("OnHealthBelow 时的阈值（0-1，如 0.2 = 20%）")]
    [Range(0f, 1f)] public float healthThreshold = 0.2f;

    [Header("执行效果")]
    [Tooltip("条件满足时执行的效果（可嵌套其他 ItemEffectBase）")]
    public ItemEffectBase executeEffect;

    [Header("冷却与次数")]
    [Tooltip("触发冷却（秒），0 = 无冷却")]
    public float cooldown;

    [Tooltip("最大触发次数，0 = 无限")]
    public int maxTriggerCount;

    private float _lastTriggerTime = -999f;
    private int _triggerCount;
    private bool _isSubscribed;

    // 缓存的组件引用
    private PlayerStats _stats;
    private PlayerCombat _combat;
    private PlayerSkillManager _skillManager;
    private BuffManager _buffManager;

    public override void OnAcquire(GameObject owner)
    {
        _stats = owner.GetComponent<PlayerStats>();
        _combat = owner.GetComponent<PlayerCombat>();
        _skillManager = owner.GetComponent<PlayerSkillManager>();
        _buffManager = owner.GetComponent<BuffManager>();

        SubscribeEvents(owner);
        _isSubscribed = true;
    }

    public override void OnRemove(GameObject owner)
    {
        UnsubscribeEvents();
        _isSubscribed = false;
    }

    private void SubscribeEvents(GameObject owner)
    {
        switch (triggerEvent)
        {
            case ItemTriggerEvent.OnDamaged:
                if (_stats != null) _stats.OnHealthChanged += HandleHealthChanged;
                break;
            case ItemTriggerEvent.OnAttack:
                if (_combat != null) _combat.OnShoot += HandleAttack;
                break;
            case ItemTriggerEvent.OnSkillCast:
                if (_skillManager != null) _skillManager.OnSkillCast += HandleSkillCast;
                break;
            case ItemTriggerEvent.OnKill:
                // 通过全局事件或 RoomManager 的敌人击败事件订阅
                break;
            case ItemTriggerEvent.OnHealthBelow:
                if (_stats != null) _stats.OnHealthChanged += HandleHealthBelow;
                break;
            // OnRoomEnter / OnRoomClear / OnDodge 等未来扩展
        }
    }

    private void UnsubscribeEvents()
    {
        if (_stats != null)
        {
            _stats.OnHealthChanged -= HandleHealthChanged;
            _stats.OnHealthChanged -= HandleHealthBelow;
        }
        if (_combat != null)
            _combat.OnShoot -= HandleAttack;
        if (_skillManager != null)
            _skillManager.OnSkillCast -= HandleSkillCast;
    }

    private void TryTrigger(GameObject owner)
    {
        // 冷却检查
        if (cooldown > 0f && Time.time - _lastTriggerTime < cooldown)
            return;

        // 次数限制
        if (maxTriggerCount > 0 && _triggerCount >= maxTriggerCount)
            return;

        _lastTriggerTime = Time.time;
        _triggerCount++;
        executeEffect?.OnAcquire(owner);
    }

    // ========== 事件处理 ==========

    private void HandleHealthChanged(float current, float max)
    {
        // OnDamaged: 只要生命减少就触发（但不包括治疗）
    }

    private void HandleAttack(Vector2 direction, float bulletSpeed, float attackStrength)
    {
        TryTrigger(_stats?.gameObject);
    }

    private void HandleSkillCast(int slotIndex, SkillData data)
    {
        TryTrigger(_stats?.gameObject);
    }

    private void HandleHealthBelow(float current, float max)
    {
        if (current / max <= healthThreshold)
            TryTrigger(_stats?.gameObject);
    }
}

/// <summary>
/// 道具触发事件类型
/// </summary>
public enum ItemTriggerEvent
{
    /// <summary>攻击时触发</summary>
    OnAttack,

    /// <summary>受伤时触发</summary>
    OnDamaged,

    /// <summary>击杀敌人时触发</summary>
    OnKill,

    /// <summary>进入房间时触发</summary>
    OnRoomEnter,

    /// <summary>清空房间时触发</summary>
    OnRoomClear,

    /// <summary>生命低于阈值时触发</summary>
    OnHealthBelow,

    /// <summary>释放技能时触发</summary>
    OnSkillCast,

    /// <summary>闪避时触发</summary>
    OnDodge
}

