using System;
using UnityEngine;

/// <summary>
/// 传递给 ItemSlotView 的纯显示数据 DTO，无行为。
/// Controller 从 ItemManager/ItemData 提取后传入 View。
/// 沿用 SkillViewData 的 struct + IEquatable<ItemViewData> 模式。
/// </summary>
public struct ItemViewData : IEquatable<ItemViewData>
{
    public Sprite Icon;
    public string Name;
    public string Description;
    public ItemQuality Quality;
    public bool IsNew;

    public bool Equals(ItemViewData other)
    {
        return ReferenceEquals(Icon, other.Icon)
            && Name == other.Name
            && Description == other.Description
            && Quality == other.Quality
            && IsNew == other.IsNew;
    }

    public override bool Equals(object obj)
        => obj is ItemViewData other && Equals(other);

    public override int GetHashCode()
    {
        unchecked
        {
            int hash = 17;
            hash = hash * 23 + (Icon != null ? Icon.GetHashCode() : 0);
            hash = hash * 23 + (Name != null ? Name.GetHashCode() : 0);
            hash = hash * 23 + (Description != null ? Description.GetHashCode() : 0);
            hash = hash * 23 + Quality.GetHashCode();
            hash = hash * 23 + IsNew.GetHashCode();
            return hash;
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 道具槽位 View —— 纯渲染，不引用任何游戏逻辑。
/// 由 ItemPanel 管理实例化，由 ItemUIController 调用 Refresh() 更新显示。
/// </summary>
public class ItemSlotView : MonoBehaviour
{
    [Header("图标")]
    [SerializeField] private Image _icon;
    [SerializeField] private GameObject _emptyIcon;

    [Header("品质框")]
    [SerializeField] private Image _qualityFrame;      // 品质颜色边框
    [SerializeField] private Image _newBadge;          // "NEW" 标记

    [Header("信息")]
    [SerializeField] private TMP_Text _nameText;
    [SerializeField] private TMP_Text _descriptionText;

    /// <summary>刷新显示</summary>
    public void Refresh(in ItemViewData data)
    {
        // 图标
        if (_icon != null)
        {
            _icon.sprite = data.Icon;
            _icon.enabled = data.Icon != null;
        }
        if (_emptyIcon != null)
            _emptyIcon.SetActive(data.Icon == null);

        // 品质框颜色
        if (_qualityFrame != null)
        {
            _qualityFrame.color = QualityToColor(data.Quality);
            _qualityFrame.gameObject.SetActive(true);
        }

        // NEW 标记
        if (_newBadge != null)
            _newBadge.gameObject.SetActive(data.IsNew);

        // 名称
        if (_nameText != null)
            _nameText.text = data.Name;

        // 描述
        if (_descriptionText != null)
            _descriptionText.text = data.Description;
    }

    /// <summary>设置为空槽位</summary>
    public void SetEmpty()
    {
        if (_icon != null) _icon.enabled = false;
        if (_emptyIcon != null) _emptyIcon.SetActive(true);
        if (_qualityFrame != null) _qualityFrame.gameObject.SetActive(false);
        if (_newBadge != null) _newBadge.gameObject.SetActive(false);
        if (_nameText != null) _nameText.text = "";
        if (_descriptionText != null) _descriptionText.text = "";
    }

    /// <summary>品质 → 颜色映射</summary>
    private static Color QualityToColor(ItemQuality quality) => quality switch
    {
        ItemQuality.Common    => new Color(0.78f, 0.78f, 0.78f),  // 白色
        ItemQuality.Uncommon  => new Color(0.36f, 0.65f, 1f),     // 蓝色
        ItemQuality.Rare      => new Color(0.68f, 0.36f, 1f),     // 紫色
        ItemQuality.Legendary => new Color(1f, 0.65f, 0.15f),     // 橙色
        _                     => Color.white
    };
}

using UnityEngine;

/// <summary>
/// 道具 UI 面板 —— 管理 ItemSlotView 的创建与刷新。
/// 类似 SkillUIPanel 的职责。
/// </summary>
public class ItemPanel : MonoBehaviour
{
    [Header("预制体与容器")]
    [SerializeField] private ItemSlotView _slotPrefab;
    [SerializeField] private Transform _container;

    /// <summary>最大显示槽位数</summary>
    [SerializeField] private int _maxSlots = 30;

    private ItemSlotView[] _views = System.Array.Empty<ItemSlotView>();

    /// <summary>Controller 调用，按数量创建槽位 View</summary>
    public void Initialize(int slotCount)
    {
        int count = Mathf.Min(slotCount, _maxSlots);

        // 清理旧子对象
        for (int i = _container.childCount - 1; i >= 0; i--)
            SafeDestroy(_container.GetChild(i).gameObject);

        _views = new ItemSlotView[count];
        for (int i = 0; i < count; i++)
        {
            ItemSlotView view = Instantiate(_slotPrefab, _container);
            view.name = $"ItemSlot_{i}";
            view.SetEmpty();
            _views[i] = view;
        }
    }

    /// <summary>Controller 调用，刷新指定槽位</summary>
    public void RefreshSlot(int index, in ItemViewData data)
    {
        if (index < 0 || index >= _views.Length)
        {
            // 自动扩容
            ExpandSlots(index + 1);
        }

        if (index >= 0 && index < _views.Length)
            _views[index]?.Refresh(data);
    }

    /// <summary>Controller 调用，将指定槽位设为空</summary>
    public void ClearSlot(int index)
    {
        if (index < 0 || index >= _views.Length) return;
        _views[index]?.SetEmpty();
    }

    /// <summary>获取指定槽位 View</summary>
    public ItemSlotView GetSlotView(int index)
    {
        if (index < 0 || index >= _views.Length) return null;
        return _views[index];
    }

    /// <summary>扩容槽位</summary>
    private void ExpandSlots(int newSize)
    {
        int target = Mathf.Min(newSize, _maxSlots);
        if (target <= _views.Length) return;

        var newViews = new ItemSlotView[target];
        for (int i = 0; i < _views.Length; i++)
            newViews[i] = _views[i];

        for (int i = _views.Length; i < target; i++)
        {
            ItemSlotView view = Instantiate(_slotPrefab, _container);
            view.name = $"ItemSlot_{i}";
            view.SetEmpty();
            newViews[i] = view;
        }

        _views = newViews;
    }

    private static void SafeDestroy(Object obj)
    {
        if (obj == null) return;
        if (Application.isPlaying)
            Destroy(obj);
        else
            DestroyImmediate(obj);
    }
}

using UnityEngine;

/// <summary>
/// 道具 UI Controller —— 监听 ItemManager（Model），通知 ItemPanel（View）。
/// 本类是 Model ↔ View 的唯一耦合点。
/// 沿用 SkillUIController 的模式。
/// </summary>
public class ItemUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private ItemManager _itemManager;

    [Header("View 引用")]
    [SerializeField] private ItemPanel _panel;

    [Header("初始容量")]
    [SerializeField] private int _initialSlotCount = 16;

    // ==================== 生命周期 ====================

    private void Start()
    {
        // 跨场景后序列化引用失效，动态查找 ItemManager
        if (_itemManager == null)
            _itemManager = ResolveItemManager();

        if (_itemManager == null)
        {
            Debug.LogError("ItemUIController: ItemManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("ItemUIController: ItemPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_initialSlotCount);

        // 订阅 Model 事件
        _itemManager.OnItemAcquired += HandleItemAcquired;
        _itemManager.OnItemRemoved += HandleItemRemoved;

        // 初始全量刷新（已有道具）
        SyncAll();
    }

    private void OnDestroy()
    {
        if (_itemManager != null)
        {
            _itemManager.OnItemAcquired -= HandleItemAcquired;
            _itemManager.OnItemRemoved -= HandleItemRemoved;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleItemAcquired(ItemData item)
    {
        // 在整个 Items 列表中查找新道具的索引
        int index = _itemManager.Items.Count - 1;
        SyncSlot(index, item, isNew: true);
    }

    private void HandleItemRemoved(ItemData item)
    {
        // 道具移除后全量同步（因为索引会变化）
        SyncAll();
    }

    // ==================== 核心同步 ====================

    /// <summary>全量同步所有道具</summary>
    private void SyncAll()
    {
        var items = _itemManager.Items;
        for (int i = 0; i < items.Count; i++)
            SyncSlot(i, items[i], isNew: false);
    }

    private void SyncSlot(int index, ItemData item, bool isNew)
    {
        ItemViewData data = new ItemViewData
        {
            Icon = item.icon,
            Name = item.itemName,
            Description = item.description,
            Quality = item.quality,
            IsNew = isNew
        };
        _panel.RefreshSlot(index, data);
    }

    // ==================== 查找 ====================

    /// <summary>运行时动态查找 ItemManager (解决跨场景序列化引用失效问题)</summary>
    private static ItemManager ResolveItemManager()
    {
        // 优先从 PlayerManager 获取持久化 Player
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<ItemManager>();

        // 兜底: Tag 查找
        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<ItemManager>() : null;
    }
}

