using System;
using UnityEngine;

public class Projectile : MonoBehaviour
{
    public enum OwnerType { Player, Enemy }

    /// <summary>全局投射物命中事件: (projectile, hitTarget)</summary>
    public static event Action<Projectile, GameObject> OnAnyProjectileHit;

    [Header("子弹参数")]
    [SerializeField] private float speed = 8f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float lifeTime = 3f;

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;

    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        _isInitialized = true;

        Destroy(gameObject, lifeTime);
    }

    void Update()
    {
        if (!_isInitialized) return;
        transform.Translate(_direction * speed * Time.deltaTime, Space.World);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        // 碰墙销毁
        if (other.CompareTag("Obstacles"))
        {
            Destroy(gameObject);
            return;
        }

        // 通过 Tag 区分敌我，通过 IDamageable 接口统一造成伤害
        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
            Destroy(gameObject);
        }
    }

    private void OnBecameInvisible()
    {
        Destroy(gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 远程攻击行为：定时朝玩家发射投射物。
/// 投射物预制体需挂有 Projectile 组件，RangedAttack 通过 Initialize() 配置其飞行参数。
/// </summary>
public class RangedAttack : MonoBehaviour, IAttackBehavior
{
    [Header("远程攻击")]
    public float damage = 8f;
    [Tooltip("两次攻击间隔（秒）")]
    public float attackCooldown = 1.5f;
    [Tooltip("投射物预制体（需挂有 Projectile 组件）")]
    public GameObject projectilePrefab;
    public float projectileSpeed = 6f;
    [Tooltip("投射物生成偏移（相对敌人位置）")]
    public Vector2 spawnOffset = Vector2.up * 0.5f;
    public float projectileLifetime = 3f;
    [Tooltip("投射物阵营：Enemy=命中Player / Player=命中Enemy（随从同化后应为Player）")]
    public Projectile.OwnerType projectileOwnerType = Projectile.OwnerType.Enemy;

    private float _lastAttackTime = -10f;

    public bool TryAttack(Transform target)
    {
        if (Time.time < _lastAttackTime + attackCooldown) return false;
        if (target == null) return false;
        if (projectilePrefab == null) return false;

        Vector2 dir = (target.position - transform.position).normalized;
        Vector2 spawnPos = (Vector2)transform.position + spawnOffset;

        GameObject obj = Instantiate(projectilePrefab, spawnPos, Quaternion.identity);
        Projectile proj = obj.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(dir, projectileSpeed, damage, projectileOwnerType);
        }
        else
        {
            // 回退：无 Projectile 组件则手动销毁
            Destroy(obj, projectileLifetime);
        }

        _lastAttackTime = Time.time;
        return true;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerCombat : MonoBehaviour
{
    [Header("射击配置")]
    [SerializeField] private GameObject bulletPrefab;

    private PlayerStats _stats;
    private float _lastShootTime = -10f;

    /// <summary>射击事件委托：参数为 (方向, 子弹速度, 攻击力)</summary>
    public event System.Action<Vector2, float, float> OnShoot;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();

        if (bulletPrefab == null)
        {
#if UNITY_EDITOR
            Debug.LogWarning("PlayerCombat: 未指定子弹预制体！");
#endif
        }
    }

    /// <summary>尝试射击，由 PlayerController 通过委托调用</summary>
    public void TryShoot()
    {
        if (bulletPrefab == null || _stats == null)
            return;

        if (Time.time < _lastShootTime + _stats.ShootCooldown)
            return;

        // 获取鼠标世界位置
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;

        Vector2 direction = (mouseWorldPos - transform.position).normalized;

        float bulletSpeed = _stats.BulletSpeed;
        float attackStrength = _stats.AttackStrength;

        // 生成子弹
        GameObject bullet = Instantiate(bulletPrefab, transform.position, Quaternion.identity);
        Projectile proj = bullet.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(direction, bulletSpeed, attackStrength, Projectile.OwnerType.Player);
        }
#if UNITY_EDITOR
        else
        {
            Debug.LogWarning("子弹预制体缺少 Projectile 组件！");
        }
#endif

        _lastShootTime = Time.time;

        OnShoot?.Invoke(direction, bulletSpeed, attackStrength);
    }
}

using UnityEngine;

/// <summary>
/// 投射物型技能效果：生成子弹/火球沿方向飞行，支持散射。
/// 右键 -> Create -> Game -> Skill Effect -> Projectile
/// </summary>
[CreateAssetMenu(fileName = "ProjectileEffect", menuName = "Game/Skill Effect/Projectile")]
public class ProjectileSkillEffect : SkillEffectBase
{
    [Header("投射物配置")]
    [Tooltip("投射物预制体（需挂载 Projectile 组件）")]
    public GameObject projectilePrefab;

    [Tooltip("飞行速度")]
    public float speed = 10f;

    [Tooltip("投射物数量（扇形散射）")]
    public int count = 1;

    [Tooltip("散射角度（仅 count > 1 时生效）")]
    [Range(0f, 180f)] public float spreadAngle = 30f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (projectilePrefab == null)
        {
            Debug.LogWarning("ProjectileSkillEffect: projectilePrefab 为空！");
            return;
        }

        Vector3 spawnPos = caster.CasterTransform.position;
        float baseDamage = caster.GetAttackStrength() * damageMultiplier;

        if (count == 1)
        {
            SpawnOne(spawnPos, direction, baseDamage, speed, ownerType);
        }
        else
        {
            float halfSpread = spreadAngle * 0.5f;
            float angleStep = count > 1 ? spreadAngle / (count - 1) : 0f;
            float baseAngle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;

            for (int i = 0; i < count; i++)
            {
                float angle = baseAngle - halfSpread + angleStep * i;
                Vector2 dir = new Vector2(
                    Mathf.Cos(angle * Mathf.Deg2Rad),
                    Mathf.Sin(angle * Mathf.Deg2Rad));
                SpawnOne(spawnPos, dir, baseDamage, speed, ownerType);
            }
        }
    }

    private void SpawnOne(Vector3 pos, Vector2 dir, float dmg, float spd,
                                  Projectile.OwnerType owner)
    {
        GameObject go = Instantiate(projectilePrefab, pos, Quaternion.identity);
        Projectile proj = go.GetComponent<Projectile>();
        if (proj == null) proj = go.AddComponent<Projectile>();
        proj.Initialize(dir, spd, dmg, owner);
    }
}

using System.Collections.Generic;
using System.Linq;
using UnityEngine;

/// <summary>
/// 技能库（ScriptableObject）—— 所有技能的唯一工厂入口。
/// 右键 -> Create -> Game -> Skill Library 创建。
/// </summary>
[CreateAssetMenu(fileName = "SkillLibrary", menuName = "Game/Skill Library")]
public class SkillLibrary : ScriptableObject
{
    [SerializeField] private List<SkillData> _allSkills;

    /// <summary>所有技能列表</summary>
    public IReadOnlyList<SkillData> AllSkills => _allSkills;

    /// <summary>通过 ID 查找技能数据</summary>
    public SkillData GetById(string skillId)
    {
        return _allSkills?.Find(s => s.skillId == skillId);
    }

    /// <summary>
    /// 创建完整可用的技能实例（SkillLibrary 是唯一工厂入口）。
    /// 自动注入 OnExecute 委托，优先使用 skillEffect 策略，其次 projectilePrefab。
    /// </summary>
    public SkillInstance CreateSkillInstance(string skillId)
    {
        SkillData data = GetById(skillId);
        if (data == null)
        {
            Debug.LogWarning($"SkillLibrary: 未找到 skillId='{skillId}'");
            return null;
        }

        SkillInstance instance = new SkillInstance(data);

        // 注入 OnExecute 委托
        instance.OnExecute += (caster, direction) =>
        {
            Projectile.OwnerType ownerType = caster.GetOwnerType();

            if (data.skillEffect != null)
            {
                data.skillEffect.Execute(caster, direction,
                    instance.CurrentDamageMultiplier, ownerType);
            }
            else if (data.projectilePrefab != null)
            {
                // 旧方式兼容：直接生成投射物
                GameObject go = Instantiate(data.projectilePrefab,
                    caster.CasterTransform.position, Quaternion.identity);
                Projectile proj = go.GetComponent<Projectile>();
                if (proj == null) proj = go.AddComponent<Projectile>();
                proj.Initialize(direction, data.castRange,
                    caster.GetAttackStrength() * instance.CurrentDamageMultiplier,
                    ownerType);
            }
        };

        return instance;
    }

    /// <summary>随机获取一个技能数据</summary>
    public SkillData GetRandom()
    {
        if (_allSkills == null || _allSkills.Count == 0) return null;
        return _allSkills[Random.Range(0, _allSkills.Count)];
    }

    /// <summary>
    /// 随机创建一个技能实例
    /// </summary>
    public SkillInstance CreateRandomInstance()
    {
        SkillData data = GetRandom();
        return data != null ? new SkillInstance(data) : null;
    }

    /// <summary>随机获取 N 个不重复的技能数据</summary>
    public List<SkillData> GetRandomDistinct(int count)
    {
        if (_allSkills == null || _allSkills.Count == 0) return new List<SkillData>();

        var shuffled = _allSkills.OrderBy(_ => Random.value).ToList();
        int take = Mathf.Min(count, shuffled.Count);
        return shuffled.GetRange(0, take);
    }
}

