using System.Collections.Generic;
using UnityEngine;
using UnityEditor;

// ===================== Create all test SO assets =====================

const string basePath = "Assets/Resources/TestAssets/";
EnsureDir(basePath);
EnsureDir(basePath + "Buffs/");
EnsureDir(basePath + "Items/");
EnsureDir(basePath + "Icons/");

// ===================== 1. Create BuffData assets =====================

// 1a. Stat Buff effects
var atkBuff = CreateBuffEffect<StatBuff>(basePath + "Buffs/", "StatBuff_AttackUp");
atkBuff.statName = "AttackStrength";
atkBuff.modifier = new StatModifier { mode = StatModifier.Mode.Multiplicative, value = 1.3f };

var spdBuff = CreateBuffEffect<StatBuff>(basePath + "Buffs/", "StatBuff_SpeedUp");
spdBuff.statName = "MoveSpeed";
spdBuff.modifier = new StatModifier { mode = StatModifier.Mode.Additive, value = 2f };

// 1b. DOT Buff effects  
var poisonEffect = CreateBuffEffect<DamageOverTimeBuff>(basePath + "Buffs/", "DOT_Poison");
poisonEffect.damagePerTick = 3f;
poisonEffect.tickInterval = 1f;

var fireEffect = CreateBuffEffect<DamageOverTimeBuff>(basePath + "Buffs/", "DOT_Fire");
fireEffect.damagePerTick = 5f;
fireEffect.tickInterval = 1f;

// 1c. HOT Buff
var hotEffect = CreateBuffEffect<HealOverTimeBuff>(basePath + "Buffs/", "HOT_Regen");
hotEffect.healPerTick = 2f;
hotEffect.tickInterval = 1f;

// 1d. OnHit Buff
var poisonOnHitBuff = CreateBuffEffect<OnHitBuff>(basePath + "Buffs/", "OnHit_Poison");
var poisonDebuffData = CreateBuffData(basePath + "Buffs/", "Buff_PoisonDebuff");
poisonDebuffData.buffId = "poison_debuff";
poisonDebuffData.buffName = "中毒";
poisonDebuffData.description = "每秒受到3点伤害";
poisonDebuffData.buffType = BuffType.Debuff;
poisonDebuffData.duration = 5f;
poisonDebuffData.stackable = true;
poisonDebuffData.maxStacks = 3;
poisonDebuffData.stackBehavior = StackBehavior.Refresh;
poisonDebuffData.effect = poisonEffect;
EditorUtility.SetDirty(poisonDebuffData);

poisonOnHitBuff.onHitBuff = poisonDebuffData;
poisonOnHitBuff.procChance = 1f;
EditorUtility.SetDirty(poisonOnHitBuff);

// 1e. OnHit Heal
var healOnHitEffect = CreateBuffEffect<OnHitHealBuff>(basePath + "Buffs/", "OnHitHeal_Vampiric");
healOnHitEffect.healAmount = 3f;
healOnHitEffect.procChance = 1f;

// 1f. OnDamaged Buff (reflect)
var reflectEffect = CreateBuffEffect<OnDamagedBuff>(basePath + "Buffs/", "OnDamaged_Reflect");
reflectEffect.reflectPercent = 0.3f;

// Now create the BuffData wrappers

// Buff: 锋利
var atkBuffData = CreateBuffData(basePath + "Buffs/", "Buff_SharpBlade");
atkBuffData.buffId = "sharp_blade";
atkBuffData.buffName = "锋利";
atkBuffData.description = "攻击力提升30%";
atkBuffData.buffType = BuffType.Buff;
atkBuffData.isPermanent = true;
atkBuffData.effect = atkBuff;
EditorUtility.SetDirty(atkBuffData);

// Buff: 疾走
var spdBuffData = CreateBuffData(basePath + "Buffs/", "Buff_SwiftFoot");
spdBuffData.buffId = "swift_foot";
spdBuffData.buffName = "疾走";
