        EnsureDir(parent);
        AssetDatabase.CreateFolder(parent, parts[^1]);
    }
}

T CreateBuffEffect<T>(string folder, string name) where T : BuffEffectBase
{
    var inst = ScriptableObject.CreateInstance<T>();
