args.script:
using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

const string iconPath = "Assets/Resources/TestAssets/Icons/";

// Ensure directory
if (!AssetDatabase.IsValidFolder("Assets/Resources/TestAssets/Icons"))
    AssetDatabase.CreateFolder("Assets/Resources/TestAssets", "Icons");

// Create 6 item icons
var icons = new Dictionary<string, (Color primary, Color secondary, string shape)>
{
    { "icon_belt_of_strength",    (new Color(0.9f, 0.3f, 0.2f), new Color(0.7f, 0.15f, 0.1f), "belt") },
    { "icon_wind_boots",          (new Color(0.2f, 0.7f, 0.3f), new Color(0.1f, 0.5f, 0.2f), "boots") },
    { "icon_serpent_fang",        (new Color(0.5f, 0.2f, 0.8f), new Color(0.3f, 0.1f, 0.6f), "fang") },
    { "icon_vampiric_touch",      (new Color(0.8f, 0.1f, 0.1f), new Color(0.5f, 0.05f, 0.05f), "drop") },
    { "icon_thorn_armor",         (new Color(0.3f, 0.3f, 0.35f), new Color(0.6f, 0.55f, 0.5f), "shield") },
    { "icon_phoenix_feather",     (new Color(1f, 0.5f, 0.1f), new Color(1f, 0.3f, 0.05f), "feather") }
};

foreach (var kvp in icons)
{
    string name = kvp.Key;
    Color primary = kvp.Value.primary;
    Color secondary = kvp.Value.secondary;
    string shape = kvp.Value.shape;

    Texture2D tex = new Texture2D(64, 64, TextureFormat.RGBA32, false);
    tex.filterMode = FilterMode.Point;
    ClearTexture(tex, Color.clear);

    // Draw colored background circle
    int center = 32;
    int radius = 26;
    int innerRadius = 22;

    for (int y = 0; y < 64; y++)
    {
        for (int x = 0; x < 64; x++)
        {
            float dist = Vector2.Distance(new Vector2(x, y), new Vector2(center, center));
            if (dist < 3) continue; // center gap

            if (dist <= innerRadius)
                tex.SetPixel(x, y, primary);
            else if (dist <= radius)
                tex.SetPixel(x, y, secondary);
        }
    }

    // Draw shape-specific details
    switch (shape)
    {
        case "belt":
            // Horizontal bars for belt
            for (int y = 22; y <= 26; y++)
                for (int x = 12; x <= 52; x++)
                    if (tex.GetPixel(x, y) != Color.clear)
                        tex.SetPixel(x, y, Color.Lerp(primary, Color.white, 0.4f));
            for (int y = 38; y <= 42; y++)
                for (int x = 12; x <= 52; x++)
                    if (tex.GetPixel(x, y) != Color.clear)
                        tex.SetPixel(x, y, Color.Lerp(primary, Color.white, 0.4f));
            // Buckle
            for (int y = 28; y <= 36; y++)
                for (int x = 28; x <= 36; x++)
                    if (dist(x, y, center, center) <= 5)
                        tex.SetPixel(x, y, Color.white);
            break;

        case "boots":
            // Wing-like shape inside
            for (int y = 16; y <= 48; y++)
                for (int x = 16; x <= 48; x++)
                    if (dist(x, y, center, center - 4) <= 16 && tex.GetPixel(x, y) != Color.clear)
                        tex.SetPixel(x, y, Color.Lerp(primary, Color.white, 0.3f));
            // Speed lines
            DrawLine(tex, 24, 32, 18, 32, Color.white);
            DrawLine(tex, 24, 38, 18, 38, Color.white);
            DrawLine(tex, 24, 44, 18, 44, Color.white);
            break;

        case "fang":
            // Fang shape - triangle pointing down
            for (int y = 16; y <= 48; y++)
            {
                int halfWidth = (int)((y - 16f) / 32f * 14);
                for (int x = center - halfWidth; x <= center + halfWidth; x++)
                    if (tex.GetPixel(x, y) != Color.clear)
                        tex.SetPixel(x, y, Color.Lerp(primary, Color.white, 0.3f));
            }
            // Drop accent
            FillCircle(tex, 32, 22, 3, Color.white);
            break;

        case "drop":
            // Blood drop shape
            for (int y = 14; y <= 50; y++)
            {
                float t = (y - 14f) / 36f;
                int halfWidth = t < 0.5f ? (int)(8 * (1f - t * 2f)) : (int)(14 * (t - 0.5f) * 2f);
                for (int x = center - halfWidth; x <= center + halfWidth; x++)
                    if (tex.GetPixel(x, y) != Color.clear)
                        tex.SetPixel(x, y, Color.Lerp(primary, Color.white, 0.2f));
            }
            // Highlight
            FillCircle(tex, 32, 22, 3, Color.white);
            break;

        case "shield":
            // Shield outline
            for (int y = 12; y <= 52; y++)
            {
                float t = (y - 12f) / 40f;
                int halfWidth = (int)(18 * (1f - Mathf.Abs(t - 0.5f) * 2f) + 4);
                for (int x = center - halfWidth; x <= center + halfWidth; x++)
                    if (tex.GetPixel(x, y) != Color.clear)
                        tex.SetPixel(x, y, Color.Lerp(primary, Color.white, 0.25f));
            }
            // Cross in center
            DrawLine(tex, 28, 32, 36, 32, Color.white);
            DrawLine(tex, 32, 24, 32, 40, Color.white);
            break;

        case "feather":
            // Feather shape diagonal
            for (int y = 12; y <= 52; y++)
            {
                float t = (y - 12f) / 40f;
                int offset = (int)(Mathf.Abs(t - 0.5f) * 20);
                for (int x = center - 12 + offset; x <= center + 12 - offset; x++)
                    if (tex.GetPixel(x, y) != Color.clear)
                        tex.SetPixel(x, y, Color.Lerp(primary, Color.white, 0.25f));
            }
            // Central line
            DrawLine(tex, 32, 16, 32, 48, Color.white);
            break;
    }

    tex.Apply();

    byte[] pngData = tex.EncodeToPNG();
    string filePath = iconPath + name + ".png";
    System.IO.File.WriteAllBytes(filePath, pngData);
    AssetDatabase.ImportAsset(filePath);

    // Configure as Sprite
    TextureImporter importer = (TextureImporter)AssetImporter.GetAtPath(filePath);
    importer.textureType = TextureImporterType.Sprite;
    importer.spriteImportMode = SpriteImportMode.Single;
    importer.textureCompression = TextureImporterCompression.Uncompressed;
    importer.filterMode = FilterMode.Point;
    importer.SaveAndReimport();
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log($"=== Created {icons.Count} item icon sprites in {iconPath} ===");

// ===== Helper Functions =====

static void ClearTexture(Texture2D tex, Color c)
{
    for (int x = 0; x < tex.width; x++)
        for (int y = 0; y < tex.height; y++)
            tex.SetPixel(x, y, c);
}

static float dist(int x, int y, int cx, int cy)
{
    return Vector2.Distance(new Vector2(x, y), new Vector2(cx, cy));
}

static void DrawLine(Texture2D tex, int x0, int y0, int x1, int y1, Color c)
{
    int steps = Mathf.Max(Mathf.Abs(x1-x0), Mathf.Abs(y1-y0));
    for (int i = 0; i <= steps; i++)
    {
        float t = steps > 0 ? (float)i / steps : 0;
        int x = Mathf.RoundToInt(Mathf.Lerp(x0, x1, t));
        int y = Mathf.RoundToInt(Mathf.Lerp(y0, y1, t));
        if (x >= 0 && x < tex.width && y >= 0 && y < tex.height)
            tex.SetPixel(x, y, c);
    }
}

static void FillCircle(Texture2D tex, int cx, int cy, int r, Color c)
{
    for (int y = cy - r; y <= cy + r; y++)
        for (int x = cx - r; x <= cx + r; x++)
            if (Vector2.Distance(new Vector2(x, y), new Vector2(cx, cy)) <= r)
                if (x >= 0 && x < tex.width && y >= 0 && y < tex.height)
                    tex.SetPixel(x, y, c);
}

