using UnityEngine;
using UnityEditor;

const string iconPath = "Assets/Resources/TestAssets/Icons/";
const string itemPath = "Assets/Resources/TestAssets/Items/";

var iconMap = new System.Collections.Generic.Dictionary<string, string>
{
    { "Item_BeltOfStrength",  "icon_belt_of_strength" },
    { "Item_WindBoots",       "icon_wind_boots" },
    { "Item_SerpentFang",     "icon_serpent_fang" },
    { "Item_VampiricTouch",   "icon_vampiric_touch" },
    { "Item_ThornArmor",      "icon_thorn_armor" },
    { "Item_PhoenixFeather",  "icon_phoenix_feather" }
};

foreach (var kvp in iconMap)
{
    string itemFile = itemPath + kvp.Key + ".asset";
    string iconFile = iconPath + kvp.Value + ".png";

    var item = AssetDatabase.LoadAssetAtPath<ItemData>(itemFile);
    var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(iconFile);

    if (item != null && sprite != null)
    {
        item.icon = sprite;
        EditorUtility.SetDirty(item);
        Debug.Log($"Assigned icon '{kvp.Value}' to '{kvp.Key}'");
    }
    else
    {
        Debug.LogWarning($"Failed: item={item!=null} sprite={sprite!=null} for {kvp.Key}");
    }
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== Icon assignment complete ===");

