args.script:
using UnityEngine;
using UnityEditor;

const string itemsPath = "Assets/Resources/TestAssets/Items/";
const string prefabsPath = "Assets/Prefabs/Items/";

var mappings = new[]
{
    ("ItemPickup_BeltOfStrength",  "Item_BeltOfStrength"),
    ("ItemPickup_WindBoots",       "Item_WindBoots"),
    ("ItemPickup_SerpentFang",     "Item_SerpentFang"),
    ("ItemPickup_VampiricTouch",   "Item_VampiricTouch"),
    ("ItemPickup_ThornArmor",      "Item_ThornArmor"),
    ("ItemPickup_PhoenixFeather",  "Item_PhoenixFeather")
};

foreach (var (prefabName, itemName) in mappings)
{
    string prefabPath = prefabsPath + prefabName + ".prefab";
    string itemDataPath = itemsPath + itemName + ".asset";

    // Load and modify prefab
    var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
    var itemData = AssetDatabase.LoadAssetAtPath<ItemData>(itemDataPath);

    if (prefab == null || itemData == null)
    {
        Debug.LogWarning($"Skipping {prefabName}: prefab={prefab!=null} itemData={itemData!=null}");
        continue;
    }

    // Open prefab for editing
    var prefabInstance = PrefabUtility.LoadPrefabContents(prefabPath);
    var pickup = prefabInstance.GetComponent<ItemPickup>();
    if (pickup != null)
    {
        pickup.itemData = itemData;
    }

    // Also set the sprite renderer icon
    var sr = prefabInstance.GetComponent<SpriteRenderer>();
    if (sr != null && itemData.icon != null)
    {
        sr.sprite = itemData.icon;
    }

    // Save back
    PrefabUtility.SaveAsPrefabAsset(prefabInstance, prefabPath);
    PrefabUtility.UnloadPrefabContents(prefabInstance);

    Debug.Log($"Configured {prefabName}: itemData={itemData.itemName}, icon={itemData.icon?.name}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== All prefabs configured successfully ===");

