using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;

var scene = EditorSceneManager.GetActiveScene();

// Find SkillUICanvas
var canvas = GameObject.Find("SkillUICanvas");
if (canvas == null)
{
    Debug.LogError("SkillUICanvas not found in scene!");
    return;
}

// Create ItemPanel GameObject
var itemPanelGo = new GameObject("ItemPanel", typeof(RectTransform), typeof(ItemPanel));
itemPanelGo.transform.SetParent(canvas.transform, false);

var rect = itemPanelGo.GetComponent<RectTransform>();
rect.anchorMin = new Vector2(0.05f, 0.15f);
rect.anchorMax = new Vector2(0.25f, 0.85f);
rect.offsetMin = Vector2.zero;
rect.offsetMax = Vector2.zero;

// Add GridLayoutGroup for auto-layout
var grid = itemPanelGo.AddComponent<GridLayoutGroup>();
grid.cellSize = new Vector2(70, 70);
grid.spacing = new Vector2(6, 6);
grid.constraint = GridLayoutGroup.Constraint.FixedColumnCount;
grid.constraintCount = 4;
grid.startCorner = GridLayoutGroup.Corner.UpperLeft;
grid.startAxis = GridLayoutGroup.Axis.Horizontal;
grid.childAlignment = TextAnchor.UpperLeft;

// Add ContentSizeFitter
// var fitter = itemPanelGo.AddComponent<ContentSizeFitter>();
// fitter.verticalFit = ContentSizeFitter.FitMode.PreferredSize;

// Create ItemUIController on the same panel or on canvas
var controllerGo = new GameObject("ItemUIController", typeof(ItemUIController));
controllerGo.transform.SetParent(canvas.transform, false);

// Create the ItemSlotView prefab (programmatic, since we need UI elements)
var slotPrefabPath = "Assets/Prefabs/Items/ItemSlotView.prefab";
var existingSlot = AssetDatabase.LoadAssetAtPath<GameObject>(slotPrefabPath);

if (existingSlot == null)
{
    // Create ItemSlotView prefab
    var slotGo = new GameObject("ItemSlotView", typeof(RectTransform), typeof(ItemSlotView), typeof(Image));

    // Background
    var bgImg = slotGo.GetComponent<Image>();
    bgImg.color = new Color(0.1f, 0.1f, 0.1f, 0.6f);

    var slotRect = slotGo.GetComponent<RectTransform>();
    slotRect.sizeDelta = new Vector2(70, 70);

    // Icon child
    var iconGo = new GameObject("Icon", typeof(RectTransform), typeof(Image));
    iconGo.transform.SetParent(slotGo.transform, false);
    var iconRect = iconGo.GetComponent<RectTransform>();
    iconRect.anchorMin = new Vector2(0.1f, 0.15f);
    iconRect.anchorMax = new Vector2(0.9f, 0.85f);
    iconRect.offsetMin = Vector2.zero;
    iconRect.offsetMax = Vector2.zero;
    iconGo.name = "Icon";

    // Quality frame
    var frameGo = new GameObject("QualityFrame", typeof(RectTransform), typeof(Image));
    frameGo.transform.SetParent(slotGo.transform, false);
    var frameRect = frameGo.GetComponent<RectTransform>();
    frameRect.anchorMin = Vector2.zero;
    frameRect.anchorMax = Vector2.one;
    frameRect.offsetMin = Vector2.zero;
    frameRect.offsetMax = Vector2.zero;
    var frameImg = frameGo.GetComponent<Image>();
    frameImg.color = Color.white;
    frameGo.name = "QualityFrame";

    // NEW badge
    var newGo = new GameObject("NewBadge", typeof(RectTransform), typeof(Image));
    newGo.transform.SetParent(slotGo.transform, false);
    var newRect = newGo.GetComponent<RectTransform>();
    newRect.anchorMin = new Vector2(0.5f, 0.6f);
    newRect.anchorMax = new Vector2(1f, 1f);
    newRect.offsetMin = Vector2.zero;
    newRect.offsetMax = Vector2.zero;
    var newImg = newGo.GetComponent<Image>();
    newImg.color = new Color(1f, 0.8f, 0.1f, 0.9f);
    newGo.name = "NewBadge";

    // Save as prefab
    PrefabUtility.SaveAsPrefabAsset(slotGo, slotPrefabPath);
    Object.DestroyImmediate(slotGo);
    Debug.Log("Created ItemSlotView prefab");
}

// Configure ItemPanel
var itemPanel = itemPanelGo.GetComponent<ItemPanel>();
var slotPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(slotPrefabPath);
if (slotPrefab != null)
{
    // Use reflection or serialized field to set slotPrefab and container
    var itemPanelSo = new SerializedObject(itemPanel);
    var slotPrefabProp = itemPanelSo.FindProperty("_slotPrefab");
    var containerProp = itemPanelSo.FindProperty("_container");
    if (slotPrefabProp != null) slotPrefabProp.objectReferenceValue = slotPrefab.GetComponent<ItemSlotView>();
    if (containerProp != null) containerProp.objectReferenceValue = itemPanelGo.transform;
    itemPanelSo.ApplyModifiedProperties();
}

// Configure ItemUIController
var controller = controllerGo.GetComponent<ItemUIController>();
var controllerSo = new SerializedObject(controller);
var panelProp = controllerSo.FindProperty("_panel");
if (panelProp != null) panelProp.objectReferenceValue = itemPanel;
controllerSo.ApplyModifiedProperties();

// Mark scene dirty
EditorSceneManager.MarkSceneDirty(scene);
EditorSceneManager.SaveScene(scene);

Debug.Log($"=== Item UI setup complete in scene '{scene.name}' ===");
Debug.Log($"Created: ItemPanel (under SkillUICanvas), ItemUIController");

