using UnityEngine;
using UnityEngine.UI;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;

var scene = EditorSceneManager.GetActiveScene();

// ===== 1. Add ItemInteractionHandler to Player =====
var player = GameObject.FindGameObjectWithTag("Player");
if (player != null)
{
    var handler = player.AddComponent<ItemInteractionHandler>();
    Debug.Log("Added ItemInteractionHandler to Player");
}
else
{
    Debug.LogError("Player not found!");
    return;
}

// ===== 2. Create ItemDetailPopup under SkillUICanvas =====
var canvas = GameObject.Find("SkillUICanvas");
if (canvas == null) { Debug.LogError("No canvas!"); return; }

// Remove old popup if exists
var oldPopup = GameObject.Find("ItemDetailPopup");
if (oldPopup != null) Object.DestroyImmediate(oldPopup);

var popupGo = new GameObject("ItemDetailPopup", typeof(RectTransform), typeof(CanvasGroup), typeof(ItemDetailPopup));
popupGo.transform.SetParent(canvas.transform, false);
popupGo.layer = 5;

var popupRect = popupGo.GetComponent<RectTransform>();
popupRect.sizeDelta = new Vector2(220, 100);
popupRect.pivot = new Vector2(0.5f, 1f);

var popupCG = popupGo.GetComponent<CanvasGroup>();
popupCG.alpha = 0f;

// Background
var bgGo = new GameObject("Background", typeof(RectTransform), typeof(Image));
bgGo.transform.SetParent(popupGo.transform, false);
bgGo.layer = 5;
var bgRect = bgGo.GetComponent<RectTransform>();
bgRect.anchorMin = Vector2.zero; bgRect.anchorMax = Vector2.one;
bgRect.offsetMin = Vector2.zero; bgRect.offsetMax = Vector2.zero;
var bgImg = bgGo.GetComponent<Image>();
bgImg.color = new Color(0.05f, 0.05f, 0.1f, 0.9f);

// Icon
var iconGo = new GameObject("Icon", typeof(RectTransform), typeof(Image));
iconGo.transform.SetParent(popupGo.transform, false);
iconGo.layer = 5;
var iconRect = iconGo.GetComponent<RectTransform>();
iconRect.anchorMin = new Vector2(0f, 0.5f); iconRect.anchorMax = new Vector2(0f, 0.5f);
iconRect.pivot = new Vector2(0f, 0.5f);
iconRect.anchoredPosition = new Vector2(8, 0);
iconRect.sizeDelta = new Vector2(40, 40);
var iconImg = iconGo.GetComponent<Image>();
iconImg.preserveAspect = true;

// Name
var nameGo = new GameObject("Name", typeof(RectTransform), typeof(TextMeshProUGUI));
nameGo.transform.SetParent(popupGo.transform, false);
nameGo.layer = 5;
var nameRect = nameGo.GetComponent<RectTransform>();
nameRect.anchorMin = new Vector2(0, 1); nameRect.anchorMax = new Vector2(0, 1);
nameRect.pivot = new Vector2(0, 1);
nameRect.anchoredPosition = new Vector2(52, -6);
nameRect.sizeDelta = new Vector2(158, 24);
var nameTmp = nameGo.GetComponent<TextMeshProUGUI>();
nameTmp.fontSize = 14;
nameTmp.fontStyle = FontStyles.Bold;
nameTmp.alignment = TextAlignmentOptions.Left;

// Description
var descGo = new GameObject("Desc", typeof(RectTransform), typeof(TextMeshProUGUI));
descGo.transform.SetParent(popupGo.transform, false);
descGo.layer = 5;
var descRect = descGo.GetComponent<RectTransform>();
descRect.anchorMin = new Vector2(0, 0); descRect.anchorMax = new Vector2(1, 1);
descRect.offsetMin = new Vector2(8, 8);
descRect.offsetMax = new Vector2(-8, -30);
var descTmp = descGo.GetComponent<TextMeshProUGUI>();
descTmp.fontSize = 11;
descTmp.color = new Color(0.7f, 0.7f, 0.7f);
descTmp.alignment = TextAlignmentOptions.Left;
descTmp.enableWordWrapping = true;

// Prompt
var promptGo = new GameObject("Prompt", typeof(RectTransform), typeof(TextMeshProUGUI));
promptGo.transform.SetParent(popupGo.transform, false);
promptGo.layer = 5;
var promptRect = promptGo.GetComponent<RectTransform>();
promptRect.anchorMin = new Vector2(0, 0); promptRect.anchorMax = new Vector2(1, 0);
promptRect.pivot = new Vector2(0.5f, 0);
promptRect.anchoredPosition = new Vector2(0, 4);
promptRect.sizeDelta = new Vector2(0, 20);
var promptTmp = promptGo.GetComponent<TextMeshProUGUI>();
promptTmp.fontSize = 12;
promptTmp.fontStyle = FontStyles.Bold;
promptTmp.color = new Color(1f, 0.85f, 0.3f);
promptTmp.alignment = TextAlignmentOptions.Center;

// Bind serialized fields
var popupSo = new SerializedObject(popupGo.GetComponent<ItemDetailPopup>());
popupSo.FindProperty("_canvasGroup").objectReferenceValue = popupCG;
popupSo.FindProperty("_background").objectReferenceValue = bgImg;
popupSo.FindProperty("_icon").objectReferenceValue = iconImg;
popupSo.FindProperty("_nameText").objectReferenceValue = nameTmp;
popupSo.FindProperty("_descText").objectReferenceValue = descTmp;
popupSo.FindProperty("_promptText").objectReferenceValue = promptTmp;
popupSo.ApplyModifiedProperties();

// ===== 3. Link handler to popup =====
var handlerSo = new SerializedObject(player.GetComponent<ItemInteractionHandler>());
handlerSo.FindProperty("_detailPopup").objectReferenceValue = popupGo.GetComponent<ItemDetailPopup>();
handlerSo.ApplyModifiedProperties();

// ===== 4. Rebuild ItemPanel =====
var oldPanel = canvas.transform.Find("ItemPanel");
if (oldPanel != null) Object.DestroyImmediate(oldPanel.gameObject);

var panelGo = new GameObject("ItemPanel", typeof(RectTransform), typeof(ItemPanel), typeof(Image));
panelGo.transform.SetParent(canvas.transform, false);
panelGo.layer = 5;
var panelRect = panelGo.GetComponent<RectTransform>();
panelRect.anchorMin = new Vector2(0.05f, 0.15f);
panelRect.anchorMax = new Vector2(0.22f, 0.9f);
panelRect.offsetMin = Vector2.zero;
panelRect.offsetMax = Vector2.zero;
var panelBg = panelGo.GetComponent<Image>();
panelBg.color = new Color(0.08f, 0.08f, 0.12f, 0.7f);

// Scroll view
var viewportGo = new GameObject("Viewport", typeof(RectTransform), typeof(Image), typeof(Mask));
viewportGo.transform.SetParent(panelGo.transform, false);
viewportGo.layer = 5;
var vpRect = viewportGo.GetComponent<RectTransform>();
vpRect.anchorMin = Vector2.zero; vpRect.anchorMax = Vector2.one;
vpRect.offsetMin = new Vector2(4, 4);
vpRect.offsetMax = new Vector2(-4, -4);
var vpMask = viewportGo.GetComponent<Image>();
vpMask.color = new Color(0f, 0f, 0f, 0f);
vpMask.raycastTarget = true;

// Content container
var contentGo = new GameObject("Content", typeof(RectTransform), typeof(GridLayoutGroup));
contentGo.transform.SetParent(viewportGo.transform, false);
contentGo.layer = 5;
var contentRect = contentGo.GetComponent<RectTransform>();
contentRect.anchorMin = new Vector2(0, 1); contentRect.anchorMax = new Vector2(1, 1);
contentRect.pivot = new Vector2(0.5f, 1);
contentRect.anchoredPosition = Vector2.zero;
contentRect.sizeDelta = new Vector2(0, 0);
var grid = contentGo.GetComponent<GridLayoutGroup>();
grid.cellSize = new Vector2(64, 64);
grid.spacing = new Vector2(4, 4);
grid.constraint = GridLayoutGroup.Constraint.FixedColumnCount;
grid.constraintCount = 3;
grid.startCorner = GridLayoutGroup.Corner.UpperLeft;
grid.startAxis = GridLayoutGroup.Axis.Horizontal;
grid.childAlignment = TextAnchor.UpperLeft;

// Attach to panel
var panelSo = new SerializedObject(panelGo.GetComponent<ItemPanel>());
panelSo.FindProperty("_container").objectReferenceValue = contentGo.transform;
panelSo.FindProperty("_gridLayout").objectReferenceValue = grid;
panelSo.ApplyModifiedProperties();

// ===== 5. Update ItemUIController panel ref =====
var oldCtrl = canvas.transform.Find("ItemUIController");
if (oldCtrl != null)
{
    var ctrlSo = new SerializedObject(oldCtrl.GetComponent<ItemUIController>());
    ctrlSo.FindProperty("_panel").objectReferenceValue = panelGo.GetComponent<ItemPanel>();
    ctrlSo.ApplyModifiedProperties();
}

// ===== 6. Remove colliders from ItemPickup prefabs =====
string[] prefabPaths = {
    "Assets/Prefabs/Items/ItemPickup_Base.prefab",
    "Assets/Prefabs/Items/ItemPickup_BeltOfStrength.prefab",
    "Assets/Prefabs/Items/ItemPickup_WindBoots.prefab",
    "Assets/Prefabs/Items/ItemPickup_SerpentFang.prefab",
    "Assets/Prefabs/Items/ItemPickup_VampiricTouch.prefab",
    "Assets/Prefabs/Items/ItemPickup_ThornArmor.prefab",
    "Assets/Prefabs/Items/ItemPickup_PhoenixFeather.prefab"
};

foreach (string path in prefabPaths)
{
    var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
    if (prefab == null) { Debug.LogWarning($"Not found: {path}"); continue; }

    var contents = PrefabUtility.LoadPrefabContents(path);
    // Remove all CircleCollider2D
    foreach (var col in contents.GetComponents<CircleCollider2D>())
        Object.DestroyImmediate(col);
    PrefabUtility.SaveAsPrefabAsset(contents, path);
    PrefabUtility.UnloadPrefabContents(contents);
    Debug.Log($"Removed colliders from {System.IO.Path.GetFileName(path)}");
}

EditorSceneManager.MarkSceneDirty(scene);
EditorSceneManager.SaveScene(scene);

Debug.Log("=== Scene setup complete: ItemInteractionHandler, ItemDetailPopup, ItemPanel rebuilt, colliders removed ===");

