args.script:
using UnityEngine;
using UnityEditor;

// 1. Ensure we have an "Item" layer (or use Default)
string[] prefabPaths = {
    "Assets/Prefabs/Items/ItemPickup_Base.prefab",
    "Assets/Prefabs/Items/ItemPickup_BeltOfStrength.prefab",
    "Assets/Prefabs/Items/ItemPickup_WindBoots.prefab",
    "Assets/Prefabs/Items/ItemPickup_SerpentFang.prefab",
    "Assets/Prefabs/Items/ItemPickup_VampiricTouch.prefab",
    "Assets/Prefabs/Items/ItemPickup_ThornArmor.prefab",
    "Assets/Prefabs/Items/ItemPickup_PhoenixFeather.prefab"
};

int fixedCount = 0;
foreach (string path in prefabPaths)
{
    var contents = PrefabUtility.LoadPrefabContents(path);
    if (contents == null) { Debug.LogWarning($"Not found: {path}"); continue; }

    // Ensure CircleCollider2D exists as trigger
    var col = contents.GetComponent<CircleCollider2D>();
    if (col == null)
        col = contents.AddComponent<CircleCollider2D>();
    col.isTrigger = true;
    col.radius = 0.5f;
    col.enabled = true;

    // Ensure SpriteRenderer exists
    var sr = contents.GetComponent<SpriteRenderer>();
    if (sr == null)
    {
        sr = contents.AddComponent<SpriteRenderer>();
        sr.sprite = null; // Will be set by ItemPickup.Awake()
    }

    PrefabUtility.SaveAsPrefabAsset(contents, path);
    PrefabUtility.UnloadPrefabContents(contents);
    fixedCount++;
    Debug.Log($"Fixed {System.IO.Path.GetFileName(path)}: has collider={col!=null}, trigger={col.isTrigger}");
}

Debug.Log($"=== Fixed {fixedCount} prefabs ===");

// 2. Verify ItemDetailPopup exists and has correct serialized fields
var popup = GameObject.Find("ItemDetailPopup");
if (popup != null)
{
    var popupScr = popup.GetComponent<ItemDetailPopup>();
    var so = new SerializedObject(popupScr);
    Debug.Log($"ItemDetailPopup found, active={popup.activeSelf}");
    Debug.Log($"  _canvasGroup={so.FindProperty("_canvasGroup").objectReferenceValue != null}");
    Debug.Log($"  _background={so.FindProperty("_background").objectReferenceValue != null}");
    Debug.Log($"  _icon={so.FindProperty("_icon").objectReferenceValue != null}");
    Debug.Log($"  _nameText={so.FindProperty("_nameText").objectReferenceValue != null}");
    Debug.Log($"  _descText={so.FindProperty("_descText").objectReferenceValue != null}");
    Debug.Log($"  _promptText={so.FindProperty("_promptText").objectReferenceValue != null}");
}
else
{
    Debug.LogError("ItemDetailPopup not found in scene!");
}

