args.script:
using UnityEngine;
using UnityEditor;

// Delete old broken prefabs
string[] oldPaths = {
    "Assets/Prefabs/Items/ItemPickup_Base.prefab",
    "Assets/Prefabs/Items/ItemPickup_BeltOfStrength.prefab",
    "Assets/Prefabs/Items/ItemPickup_WindBoots.prefab",
    "Assets/Prefabs/Items/ItemPickup_SerpentFang.prefab",
    "Assets/Prefabs/Items/ItemPickup_VampiricTouch.prefab",
    "Assets/Prefabs/Items/ItemPickup_ThornArmor.prefab",
    "Assets/Prefabs/Items/ItemPickup_PhoenixFeather.prefab"
};

foreach (var p in oldPaths)
{
    if (AssetDatabase.LoadAssetAtPath<GameObject>(p) != null)
    {
        AssetDatabase.DeleteAsset(p);
        Debug.Log($"Deleted {p}");
    }
}

// Use ItemPickup_Fixed as template, duplicate and configure
string templatePath = "Assets/Prefabs/Items/ItemPickup_Fixed.prefab";

var itemDefs = new (string prefabName, string itemAsset)[]
{
    ("ItemPickup_Base",          null),
    ("ItemPickup_BeltOfStrength",  "Assets/Resources/TestAssets/Items/Item_BeltOfStrength.asset"),
    ("ItemPickup_WindBoots",       "Assets/Resources/TestAssets/Items/Item_WindBoots.asset"),
    ("ItemPickup_SerpentFang",     "Assets/Resources/TestAssets/Items/Item_SerpentFang.asset"),
    ("ItemPickup_VampiricTouch",   "Assets/Resources/TestAssets/Items/Item_VampiricTouch.asset"),
    ("ItemPickup_ThornArmor",      "Assets/Resources/TestAssets/Items/Item_ThornArmor.asset"),
    ("ItemPickup_PhoenixFeather",  "Assets/Resources/TestAssets/Items/Item_PhoenixFeather.asset"),
};

foreach (var def in itemDefs)
{
    string destPath = "Assets/Prefabs/Items/" + def.prefabName + ".prefab";

    // Duplicate template
    AssetDatabase.CopyAsset(templatePath, destPath);
    AssetDatabase.ImportAsset(destPath);

    // Load + modify
    var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(destPath);
    var contents = PrefabUtility.LoadPrefabContents(destPath);

    // Configure ItemPickup
    var pickup = contents.GetComponent<ItemPickup>();

    // Assign itemData if specified
    if (def.itemAsset != null)
    {
        var itemData = AssetDatabase.LoadAssetAtPath<ItemData>(def.itemAsset);
        pickup.itemData = itemData;

        // Also set the SpriteRenderer icon
        var sr = contents.GetComponent<SpriteRenderer>();
        if (sr != null && itemData.icon != null)
        {
            sr.sprite = itemData.icon;
        }
    }

    // Ensure collider is trigger
    var col = contents.GetComponent<CircleCollider2D>();
    col.isTrigger = true;
    col.radius = 0.5f;

    PrefabUtility.SaveAsPrefabAsset(contents, destPath);
    PrefabUtility.UnloadPrefabContents(contents);
    Debug.Log($"Created {def.prefabName}" + (def.itemAsset != null ? $" with {System.IO.Path.GetFileNameWithoutExtension(def.itemAsset)}" : ""));
}

// Delete the template
AssetDatabase.DeleteAsset(templatePath);
AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== All ItemPickup prefabs recreated with colliders ===");

