using System.Collections.Generic;
using UnityEngine;
using UnityEditor;

const string configsPath = "Assets/Resources/Map/RoomConfigs/FirstFloor/";
const string prefabsPath = "Assets/Prefabs/Items/";

// Load all item prefabs
var itemPrefabs = new List<GameObject>
{
    AssetDatabase.LoadAssetAtPath<GameObject>(prefabsPath + "ItemPickup_BeltOfStrength.prefab"),
    AssetDatabase.LoadAssetAtPath<GameObject>(prefabsPath + "ItemPickup_WindBoots.prefab"),
    AssetDatabase.LoadAssetAtPath<GameObject>(prefabsPath + "ItemPickup_SerpentFang.prefab"),
    AssetDatabase.LoadAssetAtPath<GameObject>(prefabsPath + "ItemPickup_VampiricTouch.prefab"),
    AssetDatabase.LoadAssetAtPath<GameObject>(prefabsPath + "ItemPickup_ThornArmor.prefab"),
    AssetDatabase.LoadAssetAtPath<GameObject>(prefabsPath + "ItemPickup_PhoenixFeather.prefab")
};

Debug.Log($"Loaded {itemPrefabs.Count} item prefabs");
foreach (var p in itemPrefabs)
    Debug.Log($"  {p?.name ?? "NULL"}");

// Rooms to configure
var roomConfigs = new Dictionary<string, (int min, int max)>
{
    { "RoomConfig_Room_Normal.asset",   (1, 3) },
    { "RoomConfig_Room_Treasure.asset", (2, 4) },
    { "RoomConfig_Room_Boss.asset",     (3, 4) },
    { "RoomConfig_Room_Shop.asset",     (1, 2) },
    { "RoomConfig_Room_Hidden.asset",   (2, 3) }
};

foreach (var kvp in roomConfigs)
{
    string path = configsPath + kvp.Key;
    var config = AssetDatabase.LoadAssetAtPath<RoomConfig>(path);
    if (config == null) continue;

    config.itemPool = new List<GameObject>();

    // Common items always
    if (itemPrefabs[0] != null) config.itemPool.Add(itemPrefabs[0]); // 力量腰带
    if (itemPrefabs[1] != null) config.itemPool.Add(itemPrefabs[1]); // 疾风之靴

    // Uncommon items for most rooms
    if (kvp.Key != "RoomConfig_Room_Normal.asset")
    {
        if (itemPrefabs[2] != null) config.itemPool.Add(itemPrefabs[2]); // 毒蛇之牙
        if (itemPrefabs[3] != null) config.itemPool.Add(itemPrefabs[3]); // 吸血之触
    }

    // Rare for special rooms
    if (kvp.Key != "RoomConfig_Room_Normal.asset" && kvp.Key != "RoomConfig_Room_Shop.asset")
    {
        if (itemPrefabs[4] != null) config.itemPool.Add(itemPrefabs[4]); // 荆棘铠甲
        if (itemPrefabs[5] != null) config.itemPool.Add(itemPrefabs[5]); // 凤凰之羽
    }

    config.minItems = kvp.Value.min;
    config.maxItems = kvp.Value.max;
    EditorUtility.SetDirty(config);
    Debug.Log($"Configured {kvp.Key}: pool={config.itemPool.Count}, min={kvp.Value.min}, max={kvp.Value.max}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
Debug.Log("=== RoomConfigs fixed ===");

