using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using UnityEngine;

const string SkillBase = @"D:\unity\project\WenJianGamejam_2026\.codely-cli\extensions\TMPChineseFont\skills\TMPChineseFont";

var projectRoot = Directory.GetParent(Application.dataPath)?.FullName;
if (string.IsNullOrEmpty(projectRoot))
    return "UNITY_PROJECT_ROOT_MISSING";

var pairs = new[]
{
    new
    {
        Source = Path.Combine(SkillBase, "assets", "NotoSansSC-Regular.otf"),
        Target = Path.Combine(projectRoot, "Assets", "Codely", "Fonts", "NotoSansSC-Regular.otf")
    },
    new
    {
        Source = Path.Combine(SkillBase, "assets", "OFL.txt"),
        Target = Path.Combine(projectRoot, "Assets", "Codely", "Fonts", "NotoSansSC-OFL.txt")
    }
};

var result = new StringBuilder();
foreach (var pair in pairs)
{
    string status;
    if (!File.Exists(pair.Source))
    {
        status = $"BUNDLED_SOURCE_MISSING {pair.Source}";
    }
    else if (!File.Exists(pair.Target))
    {
        status = $"TARGET_ABSENT_WILL_CREATE {pair.Target}";
    }
    else
    {
        string sourceHash, targetHash;
        using (var sha256 = SHA256.Create())
        using (var stream = File.OpenRead(pair.Source))
            sourceHash = Convert.ToBase64String(sha256.ComputeHash(stream));
        using (var sha256 = SHA256.Create())
        using (var stream = File.OpenRead(pair.Target))
            targetHash = Convert.ToBase64String(sha256.ComputeHash(stream));
        status = sourceHash == targetHash ? $"MATCH {pair.Target}" : $"CONFLICT {pair.Target}";
    }
    if (result.Length > 0) result.AppendLine();
    result.Append(status);
}

return result.ToString();

