args.script:
using System;
using TMPro;
using UnityEditor;
using UnityEngine;
using UnityEngine.TextCore.LowLevel;

const string SourceFontPath = "Assets/Codely/Fonts/NotoSansSC-Regular.otf";
const string FontAssetPath = "Assets/Codely/Fonts/NotoSansSC-Regular SDF.asset";

if (EditorApplication.isPlayingOrWillChangePlaymode)
    throw new InvalidOperationException("TMP_FONT_REQUIRES_EDIT_MODE");

var settings = TMP_Settings.instance;
if (settings == null)
    return "TMP_SETTINGS_MISSING";

AssetDatabase.ImportAsset(SourceFontPath, ImportAssetOptions.ForceSynchronousImport);
var sourceFont = AssetDatabase.LoadAssetAtPath<Font>(SourceFontPath);
if (sourceFont == null)
    return $"TMP_SOURCE_FONT_MISSING path={SourceFontPath}";
if (!sourceFont.HasCharacter('中'))
    return $"EXISTING_FONT_UNSUPPORTED path={SourceFontPath}";

var existingObject = AssetDatabase.LoadMainAssetAtPath(FontAssetPath);
var fontAsset = existingObject as TMP_FontAsset;
if (existingObject != null && fontAsset == null)
    return $"FONT_ASSET_PATH_CONFLICT path={FontAssetPath} type={existingObject.GetType().FullName}";

var created = false;
if (fontAsset == null)
{
    fontAsset = TMP_FontAsset.CreateFontAsset(sourceFont, 90, 9, GlyphRenderMode.SDFAA, 2048, 2048, AtlasPopulationMode.Dynamic, true);
    if (fontAsset == null)
        return "TMP_FONT_CREATION_FAILED";

    fontAsset.name = "NotoSansSC-Regular SDF";
    fontAsset.isMultiAtlasTexturesEnabled = true;
    AssetDatabase.CreateAsset(fontAsset, FontAssetPath);

    if (fontAsset.material != null && !EditorUtility.IsPersistent(fontAsset.material))
    {
        fontAsset.material.name = "NotoSansSC-Regular Atlas Material";
        AssetDatabase.AddObjectToAsset(fontAsset.material, fontAsset);
    }

    foreach (var atlas in fontAsset.atlasTextures ?? Array.Empty<Texture2D>())
    {
        if (atlas == null || EditorUtility.IsPersistent(atlas))
            continue;
        atlas.name = "NotoSansSC-Regular Atlas";
        AssetDatabase.AddObjectToAsset(atlas, fontAsset);
    }
    created = true;
}

fontAsset.atlasPopulationMode = AtlasPopulationMode.Dynamic;
fontAsset.isMultiAtlasTexturesEnabled = true;

var fallbacks = TMP_Settings.fallbackFontAssets;
if (fallbacks == null)
    return "TMP_FALLBACK_LIST_MISSING";

var fallbackAdded = false;
if (!fallbacks.Contains(fontAsset))
{
    fallbacks.Add(fontAsset);
    fallbackAdded = true;
}

EditorUtility.SetDirty(fontAsset);
EditorUtility.SetDirty(settings);
AssetDatabase.SaveAssets();
AssetDatabase.Refresh();

return $"TMP_CHINESE_FONT_READY created={created} fallbackAdded={fallbackAdded} fontAsset={FontAssetPath}";

